@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&display=swap');

:root {
  color-scheme: dark;
  font-family: 'Rajdhani', system-ui, sans-serif;
  background: #040b17;
  color: #d7f5ff;
  font-synthesis: none;
  text-rendering: geometricPrecision;
}

* { box-sizing: border-box; }

html, body, #root { width: 100%; height: 100%; margin: 0; overflow: hidden; }

button { font: inherit; }

.game-shell { position: relative; width: 100%; height: 100%; background: #040b17; }
.game-canvas { position: absolute; inset: 0; }

.hud { position: absolute; inset: 0; pointer-events: none; text-transform: uppercase; letter-spacing: .12em; }
.hud__top { display: flex; justify-content: space-between; align-items: flex-start; padding: 22px 28px; }
.hud__cluster { display: flex; gap: 24px; align-items: flex-start; }
.hud__label { color: #78a4bb; font-size: 11px; line-height: 1; }
.hud__value { margin-top: 4px; color: #e8fbff; font-size: 25px; font-weight: 700; letter-spacing: .08em; }
.hud__value--score { color: #ffe18a; }

.shield { width: 132px; height: 8px; margin-top: 9px; overflow: hidden; border: 1px solid rgba(140, 218, 241, .55); background: rgba(0, 23, 46, .65); transform: skewX(-18deg); }
.shield__fill { height: 100%; background: linear-gradient(90deg, #ff815e, #ffd36f 45%, #75f4da); box-shadow: 0 0 14px #61e7df; transition: width 120ms linear; }

.hud__mission { position: absolute; top: 25px; left: 50%; transform: translateX(-50%); text-align: center; }
.hud__mission strong { display: block; color: #a5e8ff; font-size: 13px; }
.hud__mission span { display: block; margin-top: 5px; color: rgba(170, 215, 231, .72); font-size: 10px; }

.team { position: absolute; right: 28px; bottom: 27px; display: grid; gap: 7px; width: 150px; }
.team__member { display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-left: 2px solid #3c6c83; background: rgba(4, 17, 35, .62); color: #a5ccda; font-size: 11px; }
.team__member--ready { border-color: #6ef0d0; color: #dcfff8; }
.team__member--down { border-color: #ea6b61; color: #ec9b90; opacity: .7; }
.team__role { color: #6c8b9b; font-size: 9px; }

.status { position: absolute; left: 50%; bottom: 30px; transform: translateX(-50%); color: #c6f5ff; font-size: 13px; text-shadow: 0 0 13px #3ed4ff; }
.status--danger { color: #ff9a81; text-shadow: 0 0 13px #ff4b35; }

.crosshair { position: absolute; top: 50%; left: 50%; width: 220px; height: 220px; transform: translate(-50%, -50%); border: 1px solid rgba(105, 225, 245, .12); border-radius: 50%; }
.crosshair::before, .crosshair::after { content: ''; position: absolute; background: rgba(125, 236, 255, .32); }
.crosshair::before { top: 50%; left: 17%; width: 66%; height: 1px; }
.crosshair::after { top: 17%; left: 50%; width: 1px; height: 66%; }

.controls { position: absolute; left: 28px; bottom: 25px; color: rgba(167, 206, 220, .62); font-size: 10px; line-height: 1.7; }
.controls kbd { padding: 1px 4px; border: 1px solid rgba(148, 213, 231, .27); color: #bcf7ff; background: rgba(20, 52, 70, .55); }

.overlay { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(2, 8, 18, .5); backdrop-filter: blur(6px); pointer-events: auto; }
.overlay__card { width: min(460px, calc(100% - 32px)); padding: 36px; border: 1px solid rgba(133, 224, 248, .45); background: linear-gradient(145deg, rgba(10, 36, 59, .94), rgba(4, 13, 29, .95)); box-shadow: 0 0 70px rgba(36, 167, 218, .2); text-align: center; }
.overlay__eyebrow { color: #69e4ee; font-size: 11px; letter-spacing: .28em; }
.overlay h1 { margin: 9px 0 10px; color: #f1fdff; font-size: clamp(30px, 8vw, 58px); line-height: .95; letter-spacing: .09em; }
.overlay p { margin: 0 auto 24px; max-width: 330px; color: #a3c6d4; font-size: 14px; line-height: 1.4; letter-spacing: .04em; text-transform: none; }
.overlay button { padding: 11px 23px; border: 1px solid #6ce6ed; color: #041521; background: #8af5e4; cursor: pointer; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }
.overlay button:hover { background: #d7fff7; box-shadow: 0 0 24px rgba(110, 240, 208, .6); }

@media (max-width: 640px) {
  .hud__top { padding: 14px; }
  .hud__cluster { gap: 12px; }
  .hud__value { font-size: 19px; }
  .hud__mission { top: 15px; }
  .team { right: 14px; bottom: 14px; width: 128px; }
  .controls { left: 14px; bottom: 14px; max-width: 160px; }
  .crosshair { width: 150px; height: 150px; }
}

